                cp = ps_gettext(line+length("%%PageMedia:"), NULL);
                for (dmp = doc->media, i=0; i<doc->nummedia; i++, dmp++) {
                    if (cp && strcmp(cp, dmp->name) == 0) {
                        doc->pages[doc->numpages].media = dmp;
